function integrityRequireFreshApi():void
{if(!class_exists(O\AssignmentOrderOriginalMariaDbFreshTerminalReaderFactory::class))throw new TestFailure('INTENDED_RED: real fresh-reader factory declaration absent');}
function integrityFreshConfig(S\OriginalIntegrityDatabase $f,array $changes=[]):O\AssignmentOrderOriginalFreshReaderConfig
{return new O\AssignmentOrderOriginalFreshReaderConfig(...($changes+['databaseHost'=>$f->host,'databasePort'=>$f->port,'databaseName'=>$f->database,'databaseUser'=>$f->user,'databasePasswordFile'=>$f->passwordFile,'tablePrefix'=>$f->prefix]));}
function integrityChildFresh(S\OriginalIntegrityDatabase $f,array $configuration):array
{
    $r=S\OriginalIntegrityFreshProcess::run($f,'00000000-0000-4000-8000-000000000001',$configuration);
    if($r['exit']===42)throw new TestFailure('INTENDED_RED: real fresh-reader child API absent');
    assertSameValue(false,$r['timedOut'],'fresh proof child bounded to ten seconds');assertSameValue(0,$r['exit'],'fresh child protocol exits successfully');assertSameValue('',$r['error'],'no raw child exception/SQL/config output');
    $v=json_decode($r['out'],true,32,JSON_THROW_ON_ERROR);assertSameValue(true,$v['opened'],'read-only configured factory really opened, unavailable-all cannot pass');assertSameValue('closed',$v['close'],'child closes its owned reader');return $v;
}
$f=null;$readUser=null;$userCreated=false;
try{
    $f=new S\OriginalIntegrityDatabase();$token=substr($f->database,-12);$readUser='u_aoou_fresh_'.$token;$readPassword=bin2hex(random_bytes(16));$readPasswordFile=$f->control.'/reader-password';
    try{$f->db->query('CREATE USER '.$f->q($readUser)."@'%' IDENTIFIED BY ".$f->q($readPassword).' WITH MAX_STATEMENT_TIME 2');$userCreated=true;$f->db->query('GRANT SELECT ON `'.$f->database.'`.* TO '.$f->q($readUser)."@'%'");}
    catch(Throwable){throw new RuntimeException('SETUP_FAILURE: owned read-only principal unavailable');}
